<script setup>
import {ref,computed,onUnmounted} from 'vue';import DateInput from '../components/DateInput.vue';import BaseModal from '../components/BaseModal.vue';import InstallmentsEditor from '../components/InstallmentsEditor.vue';
import {state,company,api,scope,useResource,notify,ask,changed} from '../lib/workspace';import {money,date,amount,cents,inputMoney,periodDate,uid,normalized,statusLabel} from '../lib/format';
const kind=ref('payable'),query=ref(''),status=ref('open'),show=ref(false),mode=ref('new'),busy=ref(false),error=ref(''),form=ref({}),selected=ref(null),context=ref({}),selection=ref([]);let baseline='';
const {data,error:loadError}=useResource(async()=>{if(!state.companyId)return {titles:[],accounts:[],documents:[],participants:[]};const[titles,accounts,documents,participants,agreements]=await Promise.all([api(scope('/titles')),api(scope('/accounts')),api(scope(`/documents?period=${state.period}`)),api(scope('/masters/participant')),api(scope('/renegotiations'))]);return {titles,accounts,documents,participants,agreements};},{titles:[],accounts:[],documents:[],participants:[],agreements:[]});
const titles=computed(()=>data.value.titles.filter(t=>t.kind===kind.value));const filtered=computed(()=>titles.value.filter(t=>(!status.value||(status.value==='open'?t.balance_cents>0:t.status===status.value))&&normalized(`${t.description} ${t.partner_name} ${t.document}`).includes(normalized(query.value))));
const balance=computed(()=>titles.value.reduce((s,t)=>s+t.balance_cents,0));const chosen=computed(()=>titles.value.filter(t=>selection.value.includes(t.id)&&t.balance_cents>0));const renegTotal=computed(()=>chosen.value.reduce((s,t)=>s+t.balance_cents,0)+(cents(form.value.interest)||0)-(cents(form.value.discount)||0));const cash=computed(()=>(cents(form.value.amount)||0)+(cents(form.value.interest)||0)+(cents(form.value.fine)||0)-(cents(form.value.discount)||0));
function open(t=null,view=''){mode.value=view||(t?'settle':'new');selected.value=t;context.value={id:state.companyId,name:company.value.name,period:state.period};form.value={kind:kind.value,description:'',partner_name:'',document:'',document_id:null,issue_date:periodDate(state.period),due_date:periodDate(state.period),date:periodDate(state.period),amount:t?inputMoney(t.balance_cents):'',interest:'0,00',fine:'0,00',discount:'0,00',reason:'',idempotency_key:uid(),integrate:false,principal_account:'',cash_account:'',charges_account:'',discount_account:'',installments:[],version:t?.version};baseline=JSON.stringify(form.value);error.value='';show.value=true;state.editor={name:'Operação financeira',companyId:state.companyId};}
async function close(){if(busy.value)return;if(!['history','agreements'].includes(mode.value)&&baseline!==JSON.stringify(form.value)&&!await ask({title:'Descartar edição?',message:'As alterações financeiras ainda não foram salvas.',confirmLabel:'Descartar'}))return;show.value=false;state.editor=null;}
function lines(){const f=form.value,p=cents(f.amount),charges=cents(f.interest)+cents(f.fine),discount=cents(f.discount),pay=selected.value.kind==='payable';const rows=[];const add=(id,value,debit)=>{if(value)rows.push({account_id:Number(id),debit:debit?amount(inputMoney(value)):'0.00',credit:debit?'0.00':amount(inputMoney(value))});};add(f.principal_account,p,pay);add(f.charges_account,charges,pay);add(f.cash_account,cash.value,!pay);add(f.discount_account,discount,!pay);return rows;}
async function save(){busy.value=true;error.value='';try{const payload={...form.value,amount:amount(form.value.amount),interest:amount(form.value.interest),fine:amount(form.value.fine),discount:amount(form.value.discount)};if(mode.value==='new'){await api(scope('/titles',context.value.id),{method:'POST',body:payload});}else if(mode.value==='renegotiate'){payload.title_ids=chosen.value.map(t=>t.id);payload.versions=Object.fromEntries(chosen.value.map(t=>[t.id,t.version]));payload.installments=payload.installments.map(p=>({...p,amount:amount(p.amount)}));await api(scope('/titles/renegotiate',context.value.id),{method:'POST',body:payload});selection.value=[];}else{if(payload.integrate)payload.lines=lines();await api(scope(`/titles/${selected.value.id}/settle`,context.value.id),{method:'POST',body:payload});}show.value=false;state.editor=null;changed();notify(mode.value==='renegotiate'?'Renegociação registrada; confira os novos títulos.':'Operação financeira registrada.');}catch(e){error.value=e.message;}finally{busy.value=false;}}
async function reverse(s){const reason=await ask({title:'Estornar baixa',message:'O saldo do título será recomposto. O lançamento contábil desta baixa, quando houver, também será estornado.',inputLabel:'Justificativa',required:true,confirmLabel:'Estornar baixa',danger:true});if(!reason)return;busy.value=true;error.value='';try{const r=await api(scope(`/settlements/${s.id}/reverse`,context.value.id),{method:'POST',body:{date:form.value.date,reason,idempotency_key:uid()}});selected.value=r.title;changed();notify('Baixa estornada.');}catch(e){error.value=e.message;}finally{busy.value=false;}}
async function undoAgreement(a){const reason=await ask({title:'Reverter renegociação',message:'Os novos títulos sem movimentos serão cancelados e os saldos restantes dos títulos originais serão reativados.',inputLabel:'Justificativa',required:true,confirmLabel:'Reverter acordo'});if(!reason)return;busy.value=true;try{await api(scope(`/renegotiations/${a.id}/reverse`,context.value.id),{method:'POST',body:{date:periodDate(context.value.period),reason,idempotency_key:uid()}});changed();notify('Renegociação revertida.');}catch(e){error.value=e.message;}finally{busy.value=false;}}
onUnmounted(()=>{if(show.value)state.editor=null;});
</script>
<template><div class="view"><header class="view-heading"><div><div class="eyebrow">GESTÃO FINANCEIRA</div><h1>Contas a pagar e receber</h1><p>Títulos, parcelas, baixas e histórico de cada operação.</p></div><div class="actions"><button class="button" @click="open(null,'agreements')">Renegociações</button><button class="button outline" @click="open(null,'renegotiate')" :disabled="!chosen.length">Renegociar selecionados ({{chosen.length}})</button><button class="button primary" @click="open()">Novo título</button></div></header><div class="finance-top"><div class="segmented"><button :class="{selected:kind==='payable'}" @click="kind='payable';selection=[]">A pagar</button><button :class="{selected:kind==='receivable'}" @click="kind='receivable';selection=[]">A receber</button></div><div class="mini-metric"><span>Saldo em aberto</span><strong>{{money(balance)}}</strong></div></div><p v-if="loadError" class="message error">{{loadError}}</p><section class="panel"><div class="table-toolbar"><input v-model="query" placeholder="Título, pessoa ou documento" aria-label="Pesquisar títulos"/><select v-model="status" aria-label="Situação financeira"><option value="open">Em aberto e parciais</option><option value="settled">Baixados</option><option value="renegotiated">Renegociados</option><option value="cancelled">Cancelados</option><option value="">Todas</option></select><span>{{filtered.length}} títulos</span></div><div class="table-scroll"><table><thead><tr><th>Selecionar</th><th>Vencimento</th><th>Título / pessoa</th><th>Documento</th><th class="right">Valor</th><th class="right">Saldo</th><th>Situação</th><th>Ações</th></tr></thead><tbody><tr v-for="t in filtered" :key="t.id"><td><input type="checkbox" v-model="selection" :value="t.id" :disabled="t.balance_cents<=0" :aria-label="`Selecionar título ${t.id}`"/></td><td>{{date(t.due_date)}}</td><td><strong>{{t.description}}</strong><small class="cell-secondary">{{t.partner_name}}</small></td><td>{{t.document}}</td><td class="right">{{money(t.amount_cents)}}</td><td class="right">{{money(t.balance_cents)}}</td><td>{{t.status==='renegotiated'?'Renegociado':statusLabel(t.status)}}</td><td><div class="actions"><button v-if="t.balance_cents>0" class="button small outline" @click="open(t)">Baixar</button><button class="button small" @click="open(t,'history')">Histórico</button></div></td></tr></tbody></table></div></section>
<BaseModal v-if="show" :title="({new:'Novo título financeiro',settle:'Registrar baixa',history:'Histórico financeiro',agreements:'Histórico de renegociações',renegotiate:'Renegociar títulos'})[mode]" :subtitle="`${context.name} · ${context.period}`" wide @close="close"><p v-if="error" class="message error" role="alert">{{error}}</p><form id="finance-form" @submit.prevent="save"><template v-if="mode==='new'"><div class="form-grid"><label>Tipo<select v-model="form.kind"><option value="payable">Conta a pagar</option><option value="receivable">Conta a receber</option></select></label><label>Documento<input v-model="form.document"/></label><label class="span-2">Descrição *<input v-model="form.description" required/></label><label class="span-2">Participante cadastrado<select v-model.number="form.participant_id" @change="form.partner_name=data.participants.find(p=>p.id===form.participant_id)?.name||form.partner_name"><option :value="null">Identificação manual</option><option v-for="p in data.participants.filter(p=>p.active)" :key="p.id" :value="p.id">{{p.code}} · {{p.name}}</option></select></label><label class="span-2">Cliente / fornecedor<input v-model="form.partner_name" list="financial-participants"/><datalist id="financial-participants"><option v-for="p in data.participants" :key="p.id" :value="p.name"/></datalist></label><label>Emissão *<DateInput v-model="form.issue_date" required/></label><label>Vencimento *<DateInput v-model="form.due_date" required/></label><label>Valor (R$) *<input v-model="form.amount" inputmode="decimal" required/></label><label>Documento fiscal<select v-model.number="form.document_id"><option :value="null">Avulso</option><option v-for="d in data.documents" :key="d.id" :value="d.id">{{d.number}} · {{d.partner_name}}</option></select></label></div></template>
<template v-if="mode==='settle'"><p><strong>{{selected.description}}</strong> · Saldo: {{money(selected.balance_cents)}}</p><div class="form-grid three"><label>Data da baixa *<DateInput v-model="form.date" required/></label><label>Principal (R$) *<input v-model="form.amount" required inputmode="decimal"/></label><label>Juros (R$)<input v-model="form.interest" inputmode="decimal"/></label><label>Multa (R$)<input v-model="form.fine" inputmode="decimal"/></label><label>Desconto (R$)<input v-model="form.discount" inputmode="decimal"/></label><div class="mini-metric"><span>Movimento de caixa</span><strong>{{money(cash)}}</strong></div><label class="span-3">Histórico *<input v-model="form.reason" required/></label></div><label class="choice-card"><input v-model="form.integrate" type="checkbox"/><div><strong>Contabilizar esta baixa</strong><small>Principal, encargos, desconto e caixa serão registrados nas contas escolhidas.</small></div></label><div v-if="form.integrate" class="form-grid"><label v-for="(label,key) in {principal_account:'Conta do cliente / fornecedor',cash_account:'Conta de caixa / banco',charges_account:'Conta dos juros / multas',discount_account:'Conta do desconto'}" :key="key">{{label}}<select v-model.number="form[key]" :required="['principal_account','cash_account'].includes(key)||key==='charges_account'&&(cents(form.interest)+cents(form.fine)>0)||key==='discount_account'&&cents(form.discount)>0"><option value="">Selecione</option><option v-for="a in data.accounts.filter(a=>a.analytical&&a.active)" :key="a.id" :value="a.id">{{a.access_code}} · {{a.name}}</option></select></label></div></template>
<template v-if="mode==='renegotiate'"><p>{{chosen.length}} títulos selecionados. O saldo restante será substituído pelas parcelas abaixo; baixas anteriores permanecem no histórico.</p><div class="form-grid"><label>Data da renegociação *<DateInput v-model="form.date" required/></label><label>Encargos negociados<input v-model="form.interest" inputmode="decimal"/></label><label>Desconto negociado<input v-model="form.discount" inputmode="decimal"/></label><label>Justificativa *<input v-model="form.reason" required/></label></div><InstallmentsEditor v-model="form.installments" :total="renegTotal" :date="form.date"/><p class="message warning">A renegociação não gera contabilização automática. Registre os ajustes contábeis conforme os termos do acordo.</p></template>
<template v-if="mode==='history'"><p>#{{selected.id}} · {{selected.description}} · Documento fiscal {{selected.document_id||'não vinculado'}}</p><p>Valor {{money(selected.amount_cents)}} · saldo {{money(selected.balance_cents)}} · versão {{selected.version}}</p><label>Data para eventual estorno<DateInput v-model="form.date" required/></label><div class="table-scroll"><table><thead><tr><th>Baixa</th><th>Principal</th><th>Juros / multa</th><th>Desconto</th><th>Caixa</th><th>Contabilidade</th><th>Situação</th></tr></thead><tbody><tr v-for="s in selected.settlements" :key="s.id"><td>#{{s.id}} · {{date(s.date)}}<small class="cell-secondary">{{s.reason}}</small></td><td>{{money(s.amount_cents)}}</td><td>{{money(s.interest_cents+s.fine_cents)}}</td><td>{{money(s.discount_cents)}}</td><td>{{money(s.cash_cents)}}</td><td>{{s.journal_id?'#'+s.journal_id:'Sem lançamento'}}</td><td><span v-if="s.reversed_at">Estornada em {{date(s.reversal_date)}}<small class="cell-secondary">{{s.reversal_reason}}</small></span><button v-else-if="!selected.cancelled" type="button" class="button small" @click="reverse(s)" :disabled="busy">Estornar baixa</button></td></tr></tbody></table></div><p v-if="!selected.settlements.length">Nenhuma baixa registrada.</p><p v-for="a in selected.allocations" :key="a.id">Vínculo bancário #{{a.transaction_id}} · {{money(a.amount_cents)}}</p></template>
<template v-if="mode==='agreements'"><div v-for="a in data.agreements" :key="a.id" class="assessment-entry"><strong>Acordo #{{a.id}} · {{date(a.date)}}</strong><p>{{a.reason}} · saldo renegociado {{money(a.principal_cents)}}</p><p>Originais: {{a.original_ids.join(', ')}} · novos títulos: {{a.new_title_ids.join(', ')}}</p><span v-if="a.reversed_at">Revertido</span><button v-else type="button" class="button small" @click="undoAgreement(a)" :disabled="busy">Reverter acordo</button></div></template></form><template #footer><button class="button" @click="close" :disabled="busy">{{mode==='history'?'Fechar':'Cancelar'}}</button><button v-if="!['history','agreements'].includes(mode)" class="button primary" form="finance-form" :disabled="busy">{{mode==='new'?'Salvar título':mode==='renegotiate'?'Confirmar renegociação':'Confirmar baixa'}}</button></template></BaseModal></div></template>
